@bernd-edlinger apologies, but I was wondering if you could take a look at some experimenting I've been doing here.  I'm becoming convinced that there is in fact something wrong with load/store ordering on at least our arm64 system.  Please see the attached zip file for the code I wrote and a README going through my findings.  It was a bit long to just post all of it here.

@tom-cosgrove-arm if you have any insights here, that would also be greatly appreciated.
[atomics.zip](https://github.com/user-attachments/files/19116337/atomics.zip)

Heres a minimal reproducer to my tests above:
```
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <assert.h>
#include <stdint.h>


static int shutdown = 0;

static uint64_t reader_idx = 0;
static uint64_t users = 0;

#define QP_WRITE_USE 0x1000000UL

static pthread_mutex_t write_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t retire_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t write_signal = PTHREAD_COND_INITIALIZER;
static pthread_cond_t retire_signal = PTHREAD_COND_INITIALIZER;

void *writer_fn(void *)
{
	uint64_t next_reader_val;
	uint64_t count;

	fprintf(stderr, "started writer\n");
	for (;;) {
		if (shutdown == 1)
			return NULL;

		next_reader_val = __atomic_load_n(&reader_idx, __ATOMIC_SEQ_CST);
		next_reader_val++;
		__atomic_store_n(&reader_idx, next_reader_val, __ATOMIC_SEQ_CST);
		__atomic_or_fetch(&users, QP_WRITE_USE, __ATOMIC_SEQ_CST);
		do {
			count = __atomic_load_n(&users, __ATOMIC_SEQ_CST);
			assert ((count & QP_WRITE_USE) == QP_WRITE_USE)	;
			count &= ~QP_WRITE_USE;
		} while (count != 0);
		__atomic_and_fetch(&users, ~QP_WRITE_USE, __ATOMIC_SEQ_CST);
	}
	return NULL;
}

void *reader_fn(void *)
{
	uint64_t reader_idx;
	uint64_t next_reader_idx;
	int expect_reader_increment = 0;
	uint64_t count;
	fprintf(stderr, "started reader\n");
	for (;;) {
		expect_reader_increment = 0;
		if (shutdown == 1)
			return NULL;
		reader_idx = __atomic_load_n(&reader_idx, __ATOMIC_SEQ_CST);
		count = __atomic_add_fetch(&users, 1, __ATOMIC_SEQ_CST);
		if ((count & QP_WRITE_USE) == QP_WRITE_USE)
			expect_reader_increment = 1;
		next_reader_idx = __atomic_load_n(&reader_idx, __ATOMIC_SEQ_CST);
		fprintf(stderr, "initial reader %lx, second reader_idx %lx count %lx\n", reader_idx, next_reader_idx, count);
		if (expect_reader_increment == 1) {
			assert(next_reader_idx > reader_idx);
		} else {
			assert(next_reader_idx == reader_idx);
		}
		__atomic_sub_fetch(&users, 1, __ATOMIC_SEQ_CST);
	}
	return NULL;
}

static void handle_sig(int sig, siginfo_t *info, void *arg)
{
	fprintf(stderr, "Received quit\n");
	shutdown = 1;
}

int main (int argc, char **argv)
{
	pthread_t w1, r1;
	struct sigaction sig;
	void *pret = NULL;
	int i;

	memset(&sig, 0, sizeof(struct sigaction));
	sig.sa_sigaction = handle_sig;

	if (sigaction(SIGINT, &sig, NULL)) {
		fprintf(stderr, "Failed to register signal handler\n");
		exit(1);
	}	

	pthread_create(&w1, NULL, writer_fn, (void *)1);
	pthread_create(&r1, NULL, reader_fn, (void *)1);

	while (shutdown != 1)
		pause();

	fprintf(stderr, "Shutting down\n");
	pthread_join(w1, &pret);
	pthread_join(r1, &pret);

	fprintf(stderr, "Done\n");
	exit(0);
}

```

